                let contents = case.before ^ function_ ^ case.after in
                let snapshot =
                  { Util.Text_source.name = "documents.ml"; contents }
                in
                ignore (Text.add_file db src snapshot);
                snapshot
              in
              let old = put case.query in
              let anchor =
                Text.add_anchor db src old ~expected_revision:0
                  ~start:(String.length case.before)
                  ~end_:(String.length case.before + String.length case.query)
              in
              let edited = put case.edited in
              let relocated =
                Option.get (Text.get_anchor db anchor.anchor_id)
              in
              Testo.check Testo.bool true
                (match relocated.status with
                | Text.Up_to_date _ -> true
                | _ -> false);
              (* Unchanged documents retain their original range. Relocation
                 maps the final normalized space to the whole whitespace run. *)
              let expected =
                if case.query = case.edited then case.expected_target
                else case.expected_target ^ "\n\n"
              in
              Testo.check Testo.string expected relocated.raw_contents;
              Testo.check Testo.string expected
                (String.sub edited.contents relocated.range.start
                   (relocated.range.end_ - relocated.range.start)))))

      T.doc_id =
    exec_returning_one db
      {|INSERT INTO "documents"
          (source_kind, source_name, locator, revision, content_hash, contents)
        VALUES (?, ?, ?, 0, ?, ?)
        RETURNING doc_id|}
      (source_params source locator
      @ [
