    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_revision < doc_revision_attempt|}
         select_cols)
      [] ~f:row_to_anchor
end

(* Find local alignment ranges with a rolling-row Smith-Waterman recurrence. *)

open Printf

type config = { score : char -> char -> int; gap : char -> int }

let code =
  {
    score = (fun a b -> if a = b then 2 else -2);
    gap =
      (function
      | ' '
      | '\t'
      | '\r'
      | '\n' ->
          0
      | _ -> 1);
  }

type range = { start : int; end_ : int }

type alignment = {
  query : range;
  target : range;
  score : int;
  identical_bytes : int;
}

let show_range x = sprintf "[%d,%d)" x.start x.end_
let equal_range = ( = )

let align { score; gap } query target =
  let n = String.length target in
  let previous = ref (Array.make (n + 1) 0) in
  let current = ref (Array.make (n + 1) 0) in
  (* Carry start coordinates with each score instead of storing a traceback
     matrix. Only the previous and current rows are needed. *)
  let previous_query_start = ref (Array.make (n + 1) 0) in
  let current_query_start = ref (Array.make (n + 1) 0) in
  let previous_target_start = ref (Array.make (n + 1) 0) in
  let current_target_start = ref (Array.make (n + 1) 0) in
  let previous_identical = ref (Array.make (n + 1) 0) in
  let current_identical = ref (Array.make (n + 1) 0) in
  let query_gaps =
    Array.init (String.length query) (fun i -> gap query.[i])
  in
  let target_gaps =
    Array.init (String.length target) (fun i -> gap target.[i])
  in
  if Array.exists (( > ) 0) query_gaps || Array.exists (( > ) 0) target_gaps
  then invalid_arg "Smith_waterman.align: negative gap penalty";
  let best_score = ref 0 in
  let best = ref None in
  let swap a b =
    let old = !a in
    a := !b;
    b := old
  in
  for i = 1 to String.length query do
    !current.(0) <- 0;
    !current_identical.(0) <- 0;
    for j = 1 to n do
      let value = ref 0 in
      let query_start = ref (i - 1) in
      let target_start = ref (j - 1) in
      let identical = ref 0 in
      let consider candidate row col source_query source_target count =
        if candidate > !value then begin
          value := candidate;
          identical := count;
          query_start := source_query.(col);
          target_start := source_target.(col);
          if row.(col) = 0 then begin
            query_start := i - 1;
            target_start := j - 1
          end
        end
      in
      consider
        (!previous.(j - 1) + score query.[i - 1] target.[j - 1])
        !previous (j - 1) !previous_query_start !previous_target_start
        (!previous_identical.(j - 1)
        + if query.[i - 1] = target.[j - 1] then 1 else 0);
      consider
        (!previous.(j) - query_gaps.(i - 1))
        !previous j !previous_query_start !previous_target_start
        !previous_identical.(j);
      consider
        (!current.(j - 1) - target_gaps.(j - 1))
        !current (j - 1) !current_query_start !current_target_start
        !current_identical.(j - 1);
      !current.(j) <- !value;
      !current_identical.(j) <- !identical;
      !current_query_start.(j) <- !query_start;
      !current_target_start.(j) <- !target_start;
      if !value > !best_score then begin
        best_score := !value;
        best :=
          Some
            {
              query = { start = !query_start; end_ = i };
              target = { start = !target_start; end_ = j };
              score = !value;
              identical_bytes = !identical;
            }
      end
    done;
    swap previous current;
    swap previous_query_start current_query_start;
    swap previous_target_start current_target_start;
    swap previous_identical current_identical
  done;
  !best

let substring str range = String.sub str range.start (range.end_ - range.start)

let align_subs config query target =
  match align config query target with
  | None -> None
  | Some al -> Some (al, substring query al.query, substring target al.target)
let is_whitespace = function
  | ' '
  | '\t'
  | '\n'
  | '\r' ->
      true
  | _ -> false

type normalized = { text : string; norm_to_raw : int array }

let normalize_whitespace (raw : string) : normalized =
  let n = String.length raw in
  let buf = Buffer.create n in
  let positions = ref [] in
  let i = ref 0 in
  while !i < n do
    if is_whitespace raw.[!i] then begin
      positions := !i :: !positions;
      Buffer.add_char buf ' ';
      while !i < n && is_whitespace raw.[!i] do
        incr i
      done
    end
    else begin
      positions := !i :: !positions;
      Buffer.add_char buf raw.[!i];
      incr i
    end
  done;
  positions := n :: !positions;
  (* Positions were accumulated newest-first, one per normalized byte plus
     the trailing sentinel; reverse once to put them back in order. *)
  {
    text = Buffer.contents buf;
    norm_to_raw = Array.of_list (List.rev !positions);
  }

let raw_range_of_normalized (n : normalized) ~start ~end_ =
  (n.norm_to_raw.(start), n.norm_to_raw.(end_))

let sanitize_utf8 s =
  let n = String.length s in
  let start = skip_leading_continuations s ~start:0 ~end_:n in
  let buf = Buffer.create (n - start) in
  (try
     let i = ref start in
     while !i < n do
       let d = String.get_utf_8_uchar s !i in
       let len = Uchar.utf_decode_length d in
       if Uchar.utf_decode_is_valid d then begin
         Buffer.add_substring buf s !i len;
         i := !i + len
       end
       else if !i + len >= n then
         (* This malformed unit runs up to the very end of [s]: a sequence
            truncated by slicing rather than necessarily corrupt data.
            Drop it and stop. *)
         raise Exit
       else begin
         Buffer.add_utf_8_uchar buf Uchar.rep;
         i := !i + len
       end
     done
   with
  | Exit -> ());
  Buffer.contents buf

